    let mut l: int = 0;
    let mut r: int = veclen<int>(v) - 1;
    while (l <= r) {
        let m: int = (l + r) / 2;
        let val = get<int>(v, m);
        if (val == target) {
            return some(m);
        } else if (val < target) {
            l = m + 1;
        } else {
