        for (let mut b = a + 1; b < n; b = b + 1) {
            if (get<int>(list, b) < get<int>(list, min_idx)) {
                min_idx = b;
            }
        }
        if (min_idx != a) {
            let t1 = get<int>(list, a);
            let t2 = get<int>(list, min_idx);
            set<int>(list, a, t2);
            set<int>(list, min_idx, t1);
        }
    }
}

